// src/components/Sidebar.jsx
import React from 'react';
import './Sidebar.css';

function Sidebar({ isOpen, onToggle }) {
  const handleNavClick = () => {
    // סוגר את התפריט כשבוחרים קישור
    if (onToggle) {
      onToggle();
    }
  };

  return (
    <>
      {/* כפתור המבורגר – 3 פסים בצד ימין למעלה */}
      <button
        type="button"
        className={`sidebar-toggle ${isOpen ? 'open' : ''}`}
        onClick={onToggle}
        aria-label="פתיחת תפריט ניווט"
        aria-expanded={isOpen}
        aria-controls="app-sidebar"
      >
        <span />
        <span />
        <span />
      </button>

      {/* שכבת רקע מאחורי התפריט */}
      <div
        className={`sidebar-overlay ${isOpen ? 'open' : ''}`}
        onClick={onToggle}
      />

      {/* התפריט עצמו */}
      <aside
        id="app-sidebar"
        className={`sidebar ${isOpen ? 'open' : ''}`}
        dir="rtl"
      >
        <div className="sidebar-header">
          <h2>התפריט</h2>
          <div className="sidebar-subtitle">
            ניווט בין הדוחות והתצוגות
          </div>
        </div>

        <nav className="sidebar-nav">
          <a href="#home" onClick={handleNavClick}>דף הבית</a>
          <a href="#report1" onClick={handleNavClick}>דוח 1</a>
          <a href="#report2" onClick={handleNavClick}>דוח 2</a>
          <a href="#report3" onClick={handleNavClick}>דוח 3</a>
          <a href="#report4" onClick={handleNavClick}>דוח 4</a>
          <a href="#report5" onClick={handleNavClick}>דוח 5</a>
        </nav>
      </aside>
    </>
  );
}

export default Sidebar;
